/*
 * MST_$TOUCH - Fault in the page at a virtual address
 *
 * Original address: 0x00E0DD40 (SAU2 map: MST_WIRED, MST_$TOUCH at E0DD40)
 * Size: 918 bytes (0x00E0DD40 .. 0x00E0E0D5)
 * Generated by: Claude Opus 5.5
 *
 * Locates the MST entry (MSTE) of the segment holding `virtual_addr` in the
 * current address space (private segments) or in ASID 0 (global segments),
 * then brings the page in by one of four routes:
 *
 *   - an anonymous (area) segment: AREA_$TOUCH, one page;
 *   - a caller asking for a wired page of a segment that is neither local
 *     (UID first byte non-zero) nor anonymous: MMU_$VTOP + MMAP_$WIRE only;
 *   - the OS_WIRED_$UID segment: PEB_$TOUCH when the PEB WCS is loaded;
 *   - everything else: find or activate the ASTE, AST_$TOUCH a run of
 *     pages and install them with MMU_$INSTALL_LIST.
 *
 * Frame (link.w A6,-0xa0; D2-D6/A2-A5 saved; A5 = 0xE24304, the MST data):
 *   (0x08,A6)  virtual_addr  longword (D3)
 *   (0x0C,A6)  status_ret    pointer  (A2)
 *   (0x10,A6)  wire_flag     word     (D5w, tested with `tst.w`)
 *   (-0x80,A6) ppn_list      32 longwords, the physical pages touched
 *   (-0x92,A6) page          word, page within the segment ((va >> 10) & 0x1f)
 *   D2w        seg_index     the segment's slot in the ASID's MST range,
 *                            later the page count returned by the toucher
 *   D4w        asid          PROC1_$AS_ID for private segments, 0 for global
 *   A4         MSTE + 0x400  every field is addressed (-0x400..-0x3f4,A4)
 *   A3         the ASTE
 *
 * The A5 cells used: (0x148,A5) MST_$SEG_MEM_TOP, (0x158) MST_$PRIVATE_A_SIZE,
 * (0x154) MST_$SEG_PRIVATE_B, (0x15C) MST_$SEG_GLOBAL_A, (0x15E)
 * MST_$GLOBAL_A_SIZE, (0x14E) MST_$SEG_GLOBAL_B, (0xD0) MST_ASID_BASE.
 *
 * Quirks reproduced:
 *   - The OS_WIRED_$UID arm (0x00E0DF0C) succeeds with D2 still holding the
 *     segment's MST slot, so it returns that slot number, not a page.
 *   - The anonymous arm never takes ML lock 0x14, but its failure exit
 *     (0x00E0DE92 -> 0x00E0E036) and its success exit (0x00E0E09C) release
 *     it; AREA_$TOUCH returns holding that lock.
 *   - The wired-VTOP arm (0x00E0DE9C) returns MMU_$VTOP's result whatever
 *     the status, and MMAP_$WIRE runs only when the status is clear.
 *   - status_$ast_eof becomes status_$mst_access_violation (0x40005) and
 *     file_$object_not_found becomes status_$mst_object_not_found; any other
 *     failure status is passed through.  Failure always returns 0.
 */

#include "mst/mst_internal.h"
#include "netlog/netlog.h"
#include "peb/peb.h"
#include "node/node.h"
#include "anon/anon.h"
#include "file/file.h"

/* NETLOG_$LOG_IT kind for an MST touch: `move.w #0x16,-(SP)` at 0x00E0DE36 */
#define MST_TOUCH_NETLOG_KIND 0x16

/* AST_$TOUCH flag word bits built at 0x00E0DFDA .. 0x00E0DFFC */
#define MST_TOUCH_AST_FLAG_1   0x0001  /* active segment with prot bit 2 */
#define MST_TOUCH_AST_FLAG_8   0x0008  /* prot bit 0 clear */
#define MST_TOUCH_AST_FLAG_20  0x0020  /* global segment (asid 0) */

uint32_t MST_$TOUCH(uint32_t virtual_addr, status_$t *status_ret,
                    int16_t wire_flag)
{
    uint32_t ppn_list[32];   /* (-0x80,A6) */
    uint16_t page;           /* (-0x92,A6) */
    uint32_t seg;            /* D0 = va >> 15 */
    uint16_t seg_index;      /* D2w */
    uint16_t asid;           /* D4w */
    uint16_t diff;           /* D0w */
    int16_t mst_byte_off;    /* D1w */
    uint16_t table_page;     /* D0w, one-based MSTE page */
    mst_entry_t *mste;       /* A4 - 0x400 */
    aste_t *aste;            /* A3 */
    aote_t *aote;            /* A1 */
    uint16_t ast_idx;        /* D0w */
    uint16_t ast_flags;      /* D2w */
    uint16_t count;          /* D2w */
    int16_t unlock_id;       /* the word pushed before 0x00E0E03C */
    uint32_t result;         /* D2 */

    /* 0x00E0DD56-0x00E0DD68: segment number, bounded by MST_$SEG_MEM_TOP */
    seg = virtual_addr >> 15;
    if (seg >= (uint32_t)MST_$SEG_MEM_TOP) {
        goto illegal;
    }

    /* 0x00E0DD6C-0x00E0DD7A */
    page = (uint16_t)((virtual_addr >> 10) & 0x1F);

    /* 0x00E0DD7E-0x00E0DDCA: map the segment onto its ASID's MST range */
    if ((uint16_t)seg < MST_$PRIVATE_A_SIZE) {
        seg_index = (uint16_t)seg;                        /* 0x00E0DD86 */
        asid = PROC1_$AS_ID;
    } else {
        diff = (uint16_t)((uint16_t)seg - MST_$SEG_PRIVATE_B);
        if (diff < 8) {                                   /* 0x00E0DD96 */
            seg_index = (uint16_t)(diff + MST_$PRIVATE_A_SIZE);
            asid = PROC1_$AS_ID;
        } else {
            diff = (uint16_t)((uint16_t)seg - MST_$SEG_GLOBAL_A);
            if (diff < MST_$GLOBAL_A_SIZE) {              /* 0x00E0DDB0 */
                seg_index = diff;
            } else {
                /* 0x00E0DDBA cmp.w (0x14e,A5),D2w / bcs -> illegal */
                if ((uint16_t)seg < MST_$SEG_GLOBAL_B) {
                    goto illegal;
                }
                seg_index = (uint16_t)((uint16_t)seg - MST_$SEG_GLOBAL_B +
                                       MST_$GLOBAL_A_SIZE);
            }
            asid = 0;                                     /* 0x00E0DDCA */
        }
    }

    /* 0x00E0DDCC-0x00E0DDE8: MST word of the 64-segment group; 0 = none */
    mst_byte_off = (int16_t)((uint16_t)((seg_index >> 6) +
                                        MST_ASID_BASE[asid]) * 2);
    table_page = MST[mst_byte_off / 2];
    if (table_page == 0) {
        goto illegal;
    }

    /* 0x00E0DDEC-0x00E0DE04: A4 = 0xEF6400 + page*0x400 + (slot & 0x3f)*16 */
    mste = (mst_entry_t *)ARCH_VA_TO_PTR(MST_PAGE_TABLE_BASE +
                                         (uint32_t)table_page * 0x400u +
                                         (uint32_t)(int32_t)(int16_t)((seg_index & 0x3F) << 4) -
                                         0x400u);

    /* 0x00E0DE08-0x00E0DE40 */
    if (NETLOG_$OK_TO_LOG < 0) {
        NETLOG_$LOG_IT(MST_TOUCH_NETLOG_KIND, &mste->uid.high, mste->area_id,
                       page, (uint16_t)(((mste->page_info & 0x7C) >> 2) + 1),
                       asid, (uint16_t)(virtual_addr >> 16),
                       (uint16_t)virtual_addr);
    }

    /* 0x00E0DE44-0x00E0DE4C: a non-zero first UID byte is an ordinary object */
    if ((uint8_t)(mste->uid.high >> 24) != 0) {
        goto normal;
    }

    /* 0x00E0DE50 tst.l (-0x400,A4): an empty entry */
    if (mste->uid.high == 0) {
        goto illegal;
    }

    /* 0x00E0DE58-0x00E0DE62 */
    if (mste->uid.high == ANON_$UID.high) {
        /* 0x00E0DE64-0x00E0DE98: anonymous area segment, private only */
        if (asid == 0) {
            goto illegal;
        }
        PROC1_$INHIBIT_BEGIN();
        AREA_$TOUCH((area_$handle_t *)&mste->uid.low, mste->area_id, page,
                    (int16_t)seg_index, ppn_list, status_ret);
        if (*status_ret != status_$ok) {
            unlock_id = MST_LOCK_MMU;    /* 0x00E0DE92 -> 0x00E0E036 */
            goto fail_unlock;
        }
        count = 1;                       /* 0x00E0DE96 moveq #1,D2 */
        goto install;
    }

    /* 0x00E0DE9C-0x00E0DEDC: wired request for a non-local object */
    if (wire_flag != 0) {
        ML_$LOCK(MST_LOCK_MMU);
        ppn_list[0] = MMU_$VTOP(virtual_addr, status_ret);
        if (*status_ret == status_$ok) {
            MMAP_$WIRE(ppn_list[0]);
        }
        result = ppn_list[0];            /* 0x00E0DECE, before the unlock */
        ML_$UNLOCK(MST_LOCK_MMU);
        return result;
    }

    /* 0x00E0DEE0-0x00E0DEF2: the OS wired segment */
    if (mste->uid.high != OS_WIRED_$UID.high ||
        mste->uid.low != OS_WIRED_$UID.low) {
        goto normal;
    }
    /* 0x00E0DEF4-0x00E0DF0E */
    if (PEB_$INFO.wcs_loaded >= 0) {
        goto illegal;
    }
    if ((int8_t)PEB_$TOUCH(&virtual_addr) >= 0) {
        goto illegal;
    }
    *status_ret = status_$ok;
    return (uint32_t)seg_index;          /* D2 still the MST slot */

normal:
    /* 0x00E0DF1C-0x00E0DF2E */
    PROC1_$INHIBIT_BEGIN();
    ML_$LOCK(MST_LOCK_AST);

    /* 0x00E0DF30-0x00E0DF8E: reuse the cached ASTE if it still matches */
    ast_idx = (uint16_t)(mste->flags & MSTE_FLAG_AST_MASK);
    if (ast_idx != 0) {
        aste = AST_ASTE_ENTRY(ast_idx);
        if ((int16_t)aste->flags < 0) {
            goto activate;
        }
        if (aste->segment != mste->area_id) {
            goto activate;
        }
        if ((aste->flags & ASTE_FLAG_AREA) != 0) {
            goto activate;
        }
        if (aste->aote == NULL) {
            goto activate;
        }
        aote = aste->aote;
        if ((int8_t)aote->flags < 0) {
            goto activate;
        }
        if (aote->uid.high != mste->uid.high ||
            aote->uid.low != mste->uid.low) {
            goto activate;
        }
        aste->wire_count++;              /* 0x00E0DF8A addq.b #1,(0x11,A3) */
        goto have_aste;
    }

activate:
    /* 0x00E0DF90-0x00E0DFBA */
    aste = AST_$MSTE_ACTIVATE_AND_WIRE((mste_t *)(void *)mste, status_ret);
    if (aste == NULL) {
        unlock_id = MST_LOCK_AST;        /* 0x00E0DFA6 -> 0x00E0E03C */
        goto fail_unlock;
    }
    mste->flags &= 0xFE00;
    mste->flags |= aste->seg_index;

have_aste:
    /* 0x00E0DFBE-0x00E0DFD8 */
    ML_$UNLOCK(MST_LOCK_AST);
    ML_$LOCK(MST_LOCK_MMU);

    /* 0x00E0DFDA-0x00E0DFFC */
    ast_flags = 0;
    if (asid == 0) {
        ast_flags = MST_TOUCH_AST_FLAG_20;
    }
    if ((int16_t)mste->flags < 0 &&
        (mste->flags & MSTE_FLAG_COPY_ON_WRITE) != 0) {
        ast_flags |= MST_TOUCH_AST_FLAG_1;
    }
    if ((mste->flags & MSTE_FLAG_WRITABLE) == 0) {
        ast_flags |= MST_TOUCH_AST_FLAG_8;
    }

    /* 0x00E0E000-0x00E0E034 */
    count = AST_$TOUCH(aste, NODE_$ME, page,
                       (uint16_t)(((mste->page_info & 0x7C) >> 2) + 1),
                       ppn_list, status_ret, ast_flags);
    aste->wire_count--;                  /* 0x00E0E02E subq.b #1,(0x11,A3) */
    if (count != 0) {
        goto install;
    }
    unlock_id = MST_LOCK_MMU;            /* 0x00E0E036 */

fail_unlock:
    /* 0x00E0E03C-0x00E0E066 */
    ML_$UNLOCK(unlock_id);
    PROC1_$INHIBIT_END();
    if (*status_ret == status_$ast_eof) {
        *status_ret = status_$mst_access_violation;
    } else if (*status_ret == file_$object_not_found) {
        *status_ret = status_$mst_object_not_found;
    }
    return 0;                            /* 0x00E0E068 clr.l D2 */

illegal:
    /* 0x00E0DF12 -> 0x00E0E068 */
    *status_ret = status_$reference_to_illegal_address;
    return 0;

install:
    /* 0x00E0E06C-0x00E0E088: `move.w prot; move.w asid; move.l va;
     * pea list; move.w count' (mmu/mmu.h, MMU_$INSTALL_LIST) */
    MMU_$INSTALL_LIST(count, ppn_list, virtual_addr, asid,
                      (uint16_t)(mste->flags & MSTE_FLAG_PROT_MASK) >>
                          MSTE_FLAG_PROT_SHIFT);
    if (wire_flag != 0) {
        MMAP_$WIRE(ppn_list[0]);         /* 0x00E0E090 */
    }
    ML_$UNLOCK(MST_LOCK_MMU);
    PROC1_$INHIBIT_END();

    /* 0x00E0E0B0-0x00E0E0C0: a guarded segment faults once */
    if ((mste->flags & MSTE_FLAG_MODIFIED) != 0) {
        mste->flags &= (uint16_t)~MSTE_FLAG_MODIFIED;  /* bclr.b #6,(-0x3f6,A4) */
        *status_ret = status_$mst_guard_fault;
    }
    return ppn_list[0];                  /* 0x00E0E0C6 */
}
